import { Paragraph } from '@hexa-ui/components';
import { styled } from '@hexa-ui/theme';

export const TruncatedBrandName = styled(Paragraph, {
  whiteSpace: 'nowrap',
  overflow: 'hidden',
  textOverflow: 'ellipsis',
  maxWidth: '100%',
  flexShrink: 1,
  minWidth: 0,
});
